BEGIN;
CREATE TABLE IF NOT EXISTS schema_version (version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
INSERT INTO schema_version(version) VALUES (1),(2) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS runtime_state (id integer PRIMARY KEY CHECK(id=1), clock timestamptz NOT NULL, paused boolean NOT NULL DEFAULT false);
INSERT INTO runtime_state(id,clock) VALUES (1,'2026-11-01T12:00:00Z') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS operation_event (operation_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, actor text NOT NULL, action text NOT NULL, entity_id text, details jsonb NOT NULL DEFAULT '{}', occurred_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS ingest_receipt (source_key text PRIMARY KEY, request_hash text NOT NULL, response jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS issue (issue_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, issue_type text NOT NULL, offending_record_id text NOT NULL, entity_id text NOT NULL, supporting_ids jsonb NOT NULL, created_at timestamptz NOT NULL, UNIQUE(issue_type,offending_record_id));
CREATE TABLE IF NOT EXISTS issue_review (review_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, issue_id bigint NOT NULL REFERENCES issue(issue_id), actor text NOT NULL, note text NOT NULL, created_at timestamptz NOT NULL);
CREATE SEQUENCE IF NOT EXISTS runtime_ids START 1000000;
CREATE TRIGGER operation_immutable BEFORE UPDATE OR DELETE ON operation_event FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();
CREATE TRIGGER receipt_immutable BEFORE UPDATE OR DELETE ON ingest_receipt FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();
CREATE TRIGGER issue_immutable BEFORE UPDATE OR DELETE ON issue FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();
CREATE TRIGGER review_immutable BEFORE UPDATE OR DELETE ON issue_review FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();
CREATE INDEX IF NOT EXISTS line_revision_idx ON cart_line_event(cart_line_id,revision DESC);
CREATE INDEX IF NOT EXISTS campaign_dispatch_idx ON campaign_message(campaign_id);
CREATE INDEX IF NOT EXISTS attempt_dispatch_idx ON send_attempt(dispatch_id);
CREATE INDEX IF NOT EXISTS order_cart_idx ON recovery_order(cart_id);
COMMIT;
